import React, { useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import Gallery from './Gallery';
import Tabs from './Tabs';
import { sanitizeHTML } from '../utils/security';

const PropertyDetail = ({ properties, favourites, onToggleFavourite }) => {
  const { id } = useParams();
  const [activeTab, setActiveTab] = useState('description');
  
  const property = properties.find(p => p.id === id);
  
  if (!property) {
    return (
      <div className="property-not-found">
        <h2>Property Not Found</h2>
        <Link to="/" className="btn btn-primary">Back to Search</Link>
      </div>
    );
  }

  const formatPrice = (price) => {
    return `£${price.toLocaleString()}`;
  };

  const isFavourite = favourites.includes(property.id);

  const tabContent = {
    description: (
      <div className="tab-content description">
        <div dangerouslySetInnerHTML={{ __html: sanitizeHTML(property.longDescription) }} />
        <div className="property-features">
          <h4>Key Features</h4>
          <ul>
            <li>{property.bedrooms} bedrooms</li>
            <li>{property.tenure}</li>
            <li>Added: {property.added.day} {property.added.month} {property.added.year}</li>
            <li>Postcode: {property.postcode}</li>
          </ul>
        </div>
      </div>
    ),
    floorPlan: (
      <div className="tab-content floor-plan">
        <img src={property.floorPlan} alt={`Floor plan for ${property.type}`} />
        <div className="plan-info">
          <h4>Property Dimensions</h4>
          <p>Total floor area: Approximately {property.bedrooms * 12 + 50} sq m</p>
        </div>
      </div>
    ),
    map: (
      <div className="tab-content map">
        <div className="map-container">
          <iframe
            title={`Location of ${property.location}`}
            width="100%"
            height="400"
            frameBorder="0"
            style={{ border: 0 }}
            src={`https://www.google.com/maps/embed/v1/place?key=AIzaSyBFw0Qbyq9zTFTd-tUY6dZWTgaQzuU17R8&q=${property.coordinates.lat},${property.coordinates.lng}&zoom=15`}
            allowFullScreen
          ></iframe>
        </div>
        <div className="location-info">
          <h4>Location Details</h4>
          <p>{property.location}</p>
          <p>Transport links nearby</p>
        </div>
      </div>
    )
  };

  return (
    <div className="property-detail">
      <div className="property-header">
        <Link to="/" className="back-link">
          ← Back to Search
        </Link>
        <div className="property-title">
          <h1>{property.type} in {property.location.split(',')[0]}</h1>
          <div className="property-meta">
            <span className="price">{formatPrice(property.price)}</span>
            <span className="bedrooms">{property.bedrooms} bedrooms</span>
            <span className="tenure">{property.tenure}</span>
          </div>
        </div>
        
        <button 
          className={`favourite-btn large ${isFavourite ? 'active' : ''}`}
          onClick={() => onToggleFavourite(property.id)}
        >
          {isFavourite ? '❤️ Saved to Favourites' : '🤍 Add to Favourites'}
        </button>
      </div>

      <div className="property-content">
        <div className="property-gallery-section">
          <Gallery images={property.gallery} />
        </div>
        
        <div className="property-info-section">
          <Tabs 
            tabs={[
              { id: 'description', label: 'Description' },
              { id: 'floorPlan', label: 'Floor Plan' },
              { id: 'map', label: 'Location' }
            ]}
            activeTab={activeTab}
            onTabChange={setActiveTab}
          />
          
          <div className="tab-content-wrapper">
            {tabContent[activeTab]}
          </div>
          
          <div className="property-actions">
            <button className="btn btn-primary">Request Viewing</button>
            <button className="btn btn-secondary">Download Brochure</button>
            <button className="btn btn-outline">Share Property</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PropertyDetail;
